"import re
from html.parser import HTMLParser

class IDChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.ids = {}
        self.errors = []

    def handle_starttag(self, tag, attrs):
        for attr, value in attrs:
            if attr == 'id':
                if value in self.ids:
                    self.ids[value].append(self.getpos())
                else:
                    self.ids[value] = [self.getpos()]

def check_html():
    with open('P:/home/neoroute/imc-server/web/templates/grids_audio.html', 'r', encoding='utf-8') as f:
        content = f.read()

    # Pre-strip template constructs to avoid html parsing errors
    # Replace Go template tags like {{...}} with space
    clean_content = re.sub(r'\{\{.*?\}\}', ' ', content)

    parser = IDChecker()
    parser.feed(clean_content)

    print("=== Checking Duplicate IDs ===")
    has_duplicates = False
    for id_val, positions in parser.ids.items():
        if len(positions) > 1:
            print(f"Duplicate ID '{id_val}' found at positions: {positions}")
            has_duplicates = True
    if not has_duplicates:
        print("No duplicate IDs found.")

if __name__ == '__main__':
    check_html()
"

